import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Camera, CameraOptions } from '@awesome-cordova-plugins/camera/ngx';
import { File } from '@awesome-cordova-plugins/file/ngx';
import { AndroidPermissions } from '@ionic-native/android-permissions/ngx';
import { AlertService } from 'src/app/services/alert.service';
import { base64StringToBlob } from 'blob-util';
import { Geolocation } from '@ionic-native/geolocation/ngx';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';

@Component({
  selector: 'app-center-details',
  templateUrl: './center-details.page.html',
  styleUrls: ['./center-details.page.scss'],
})
export class CenterDetailsPage implements OnInit {

  @ViewChild('jpgimage') jpgimage: ElementRef;
  headerText = {
    header: 'Select Udisecode',
    translucent: true,
  };
  addProfile: boolean;
  form: FormGroup;
  submitted: boolean;
  locationCordinates: any;
  imageActive: boolean;
  schoolList: any;
  selectedSchool: any = [];
  CenterDetailsList: any = [];
  MigrateStudList: any;
  Type: any;

  constructor(private router: Router, private fb: FormBuilder,
  private alertService: AlertService, private camera: Camera,
  private androidPermissions: AndroidPermissions, private file: File,
  private geolocation: Geolocation, private emisService: EmisService,
  private userSesstion: UserSessionService, private el: ElementRef,
  private ionStorage: IonicStorageService, private route: ActivatedRoute) { }

  ngOnInit() {
    this.initialValidator();
  }

  initialValidator(){
    this.form = this.fb.group({
      IndxId: new FormControl('', null),
      UdiseCode: new FormControl('', null),
      HmName: new FormControl('', null),
      HmMobileNo: new FormControl('', null),
      CenterName: new FormControl('', null),
      NgoName: new FormControl('', null),
      DarpanId: new FormControl('', null),
      MouStartDate: new FormControl('', null),
      MouEndDate: new FormControl('', null),
      NoOfEv: new FormControl('', null),
      FreshCount: new FormControl('', null),
      ContinueCount: new FormControl('', null),
      TotalCount: new FormControl('', null),
    })
  }

  ionViewDidEnter(){
    // this.BRTEMappedSchlListEV();
    this.getEvDetailsStore();
    this.route.queryParams.subscribe((params) => {
      this.Type = params['Type'];
    })
  }

  BRTEMappedSchlListEV(){
    debugger
    this.ionStorage.getData('BRTEMappedSchlListEV').then(res =>{
      if(res){
        this.schoolList = res.filter(dd => dd.teacher_id == this.userSesstion.emis_username());
        if(this.schoolList.length == 0){
          this.emisService.BRTEMappedSchlListEV(this.userSesstion.emis_username()).subscribe(res =>{
            if(res.dataStatus){
              this.schoolList = res.result;
              this.ionStorage.removeKey('BRTEMappedSchlListEV').then(res =>{
                this.ionStorage.insertData_Replace('BRTEMappedSchlListEV',this.schoolList)
              })
            }
          })
        }
      }else{
        this.emisService.BRTEMappedSchlListEV(this.userSesstion.emis_username()).subscribe(res =>{
          if(res.dataStatus){
            this.schoolList = res.result;
            this.ionStorage.removeKey('BRTEMappedSchlListEV').then(res =>{
              this.ionStorage.insertData_Replace('BRTEMappedSchlListEV',this.schoolList)
            })
          }
        })
      }
    })
  }

  getEvDetailsStore(){
    this.ionStorage.getData('CenterDetailsList').then(res =>{
      if(res){
        this.CenterDetailsList = res.filter(dd => dd.Type == this.Type);
        if(this.CenterDetailsList.length == 0){
          this.emisService.StcCenterDetailsGet(this.userSesstion.emis_username(), this.Type).subscribe(res =>{
            if(res.dataStatus){
              this.CenterDetailsList = res.result;
              this.ionStorage.removeKey('CenterDetailsList').then(res =>{
                this.ionStorage.insertData_Replace('CenterDetailsList',this.CenterDetailsList)
              })
            }
          })
        }
      }else{
        this.emisService.StcCenterDetailsGet(this.userSesstion.emis_username(), this.Type).subscribe(res =>{
          if(res.dataStatus){
            this.CenterDetailsList = res.result;
            this.ionStorage.removeKey('CenterDetailsList').then(res =>{
              this.ionStorage.insertData_Replace('CenterDetailsList',this.CenterDetailsList)
            })
          }
        })
      }
    })
  }

  selectSchool(event){
    debugger
    this.selectedSchool = this.schoolList.filter(dd => dd.school_udise == event);
    if(this.selectedSchool.length > 0){
      console.log(this.selectedSchool);
    }
  }

  getLatLong() {
    this.geolocation.getCurrentPosition({
      enableHighAccuracy: true,
      timeout: 10000,
      maximumAge: 0
    }).then((resp) => {
      this.locationCordinates = resp.coords;
      this.locationCordinates.latitude;
      this.locationCordinates.longitude;
  }).catch((error) => {
    if (error.message === 'Illegal Access') {
      this.alertService.alertToTurnOnPermission('Location', 'Location');
    }
      // console.log('Error getting location', error);
    });
  }

  onSave(){
    debugger
    if(this.form.valid){
      this.submitted = false;
      let data = {
        "records":
          {
            IndxId: this.form.value.IndxId,
            UserId: this.userSesstion.emis_username(), 
            UdiseCode: this.form.value.UdiseCode,
            HmName: this.form.value.HmName,
            HmMobileNo: this.form.value.HmMobileNo,
            CenterName: this.form.value.CenterName,
            NgoName: this.form.value.NgoName,
            DarpanId: this.form.value.DarpanId,
            MouStartDate: this.form.value.MouStartDate,
            MouEndDate: this.form.value.MouEndDate,
            NoOfEv: this.form.value.NoOfEv,
            FreshCount: this.form.value.FreshCount,
            ContinueCount: this.form.value.ContinueCount,
            TotalCount: this.form.value.TotalCount,
            Type: this.Type,
            Lat: this.locationCordinates?.latitude,
            Long: this.locationCordinates?.longitude
          }
      }
      this.emisService.StcCenterDetailsSave(data).subscribe(res =>{
        if(res.dataStatus){
          this.addProfile = false;
          this.initialValidator();
          this.alertService.success(res.message);
          this.emisService.StcCenterDetailsGet(this.userSesstion.emis_username(), this.Type).subscribe(res =>{
            if(res.dataStatus){
              this.CenterDetailsList = res.result;
              this.ionStorage.removeKey('CenterDetailsList').then(res =>{
                this.ionStorage.insertData_Replace('CenterDetailsList',this.CenterDetailsList)
              })
            }
          })
          if(this.form.value.IndxId){
            this.emisService.MigrateStudList(this.userSesstion.emis_username()).subscribe(res =>{
              if(res.dataStatus){
                this.MigrateStudList = res.result;
                this.ionStorage.removeKey('MigrateStudList').then(res =>{
                  this.ionStorage.insertData_Replace('MigrateStudList',this.MigrateStudList)
                })
              }else{
                this.ionStorage.removeKey('MigrateStudList').then(res =>{})
              }
            })
          }
        }else{
          this.alertService.error(res.message);
        }
      })
    }else{
      this.submitted = true;
      this.focusValidator();
    }
  }

  onEdit(data){
    console.log("data",data)
    this.addProfile = true;
    // this.selectedSchool = this.schoolList.filter(dd => dd.school_udise == +data.udiseCode);
    this.form.patchValue({
      IndxId: data.IndxId,
      UdiseCode: data.UdiseCode,
      HmName: data.HmName,
      HmMobileNo: data.HmMobileNo,
      CenterName: data.CenterName,
      NgoName: data.NgoName,
      DarpanId: data.DarpanId,
      MouStartDate: data.MouStartDate,
      MouEndDate: data.MouEndDate,
      NoOfEv: data.NoOfEv,
      FreshCount: data.FreshCount,
      ContinueCount: data.ContinueCount,
      TotalCount: data.TotalCount,
      Type: data.Type,
      Lat: this.locationCordinates?.latitude,
      Long: this.locationCordinates?.longitude
    })
    if(this.Type == 1){
      this.form.controls['UdiseCode'].setValidators(Validators.required);
      this.form.controls['HmName'].setValidators(Validators.required);
      this.form.controls['HmMobileNo'].setValidators(Validators.required);

      this.form.controls['UdiseCode'].updateValueAndValidity();
      this.form.controls['HmName'].updateValueAndValidity();
      this.form.controls['HmMobileNo'].updateValueAndValidity();
    }

    if(this.Type == 2){
      this.form.controls['CenterName'].setValidators(Validators.required);
      this.form.controls['NgoName'].setValidators(Validators.required);
      this.form.controls['DarpanId'].setValidators(Validators.required);
      this.form.controls['MouStartDate'].setValidators(Validators.required);
      this.form.controls['MouEndDate'].setValidators(Validators.required);
      this.form.controls['NoOfEv'].setValidators(Validators.required);
      this.form.controls['FreshCount'].setValidators(Validators.required);
      this.form.controls['ContinueCount'].setValidators(Validators.required);

      this.form.controls['CenterName'].updateValueAndValidity();
      this.form.controls['NgoName'].updateValueAndValidity();
      this.form.controls['DarpanId'].updateValueAndValidity();
      this.form.controls['MouStartDate'].updateValueAndValidity();
      this.form.controls['MouEndDate'].updateValueAndValidity();
      this.form.controls['NoOfEv'].updateValueAndValidity();
      this.form.controls['FreshCount'].updateValueAndValidity();
      this.form.controls['ContinueCount'].updateValueAndValidity();
    }
  }

  focusValidator(){
    const invalidControl = this.el.nativeElement.querySelector('form .ng-invalid');
    invalidControl.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
    // invalidControl.scrollTo(50, 0);
    (invalidControl as HTMLElement).focus();
  }

  navigateBack(){
    if(this.addProfile){
      this.addProfile = false;
      this.submitted = false;
      this.initialValidator();
    }else{
      this.router.navigate(['/tabs/stc-activity'], { queryParams: { Type: this.Type }});
    }
  }

  addCenterProfile(){
    this.initialValidator();
    this.addProfile = true;
    if(this.Type == 1){
      this.form.controls['UdiseCode'].setValue(this.userSesstion.udise_code());
      this.form.controls['HmName'].setValue(this.userSesstion.teacher_name());
      this.form.controls['HmMobileNo'].setValue("");

      this.form.controls['UdiseCode'].setValidators(Validators.required);
      this.form.controls['HmName'].setValidators(Validators.required);
      this.form.controls['HmMobileNo'].setValidators(Validators.required);

      this.form.controls['UdiseCode'].updateValueAndValidity();
      this.form.controls['HmName'].updateValueAndValidity();
      this.form.controls['HmMobileNo'].updateValueAndValidity();
    }

    if(this.Type == 2){
      this.form.controls['CenterName'].setValidators(Validators.required);
      this.form.controls['NgoName'].setValidators(Validators.required);
      this.form.controls['DarpanId'].setValidators(Validators.required);
      this.form.controls['MouStartDate'].setValidators(Validators.required);
      this.form.controls['MouEndDate'].setValidators(Validators.required);
      this.form.controls['NoOfEv'].setValidators(Validators.required);
      this.form.controls['FreshCount'].setValidators(Validators.required);
      this.form.controls['ContinueCount'].setValidators(Validators.required);
      this.form.controls['TotalCount'].setValidators(Validators.required);

      this.form.controls['CenterName'].updateValueAndValidity();
      this.form.controls['NgoName'].updateValueAndValidity();
      this.form.controls['DarpanId'].updateValueAndValidity();
      this.form.controls['MouStartDate'].updateValueAndValidity();
      this.form.controls['MouEndDate'].updateValueAndValidity();
      this.form.controls['NoOfEv'].updateValueAndValidity();
      this.form.controls['FreshCount'].updateValueAndValidity();
      this.form.controls['ContinueCount'].updateValueAndValidity();
      this.form.controls['TotalCount'].updateValueAndValidity();
    }
  }

  ionViewDidLeave(){
    this.submitted = false;
    this.initialValidator();
    this.CenterDetailsList = [];
  }


  onEventNum(ev){
    const fresh = this.form.value.FreshCount ? parseInt(this.form.value.FreshCount) : 0;
    const continues = this.form.value.ContinueCount ? parseInt(this.form.value.ContinueCount) : 0;
    console.log(fresh + continues)
    this.form.controls['TotalCount'].setValue(fresh + continues);
    this.form.controls['TotalCount'].updateValueAndValidity();
  }

  onEventDate(id){
    this.form.controls['MouEndDate'].setValue("");
    this.form.controls['MouEndDate'].setValidators(Validators.required);
    this.form.controls['MouEndDate'].updateValueAndValidity();
  }

}
